			declaration.JE_DeclarationReference = "B00122382";
			declaration.JE_MessageType = Customs.Business.JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = Core.Constants.AUCustoms.ImportMessagingMode.ForceCMRMessages;
			declaration.JE_DateOfFirstArrival = new ZDateTime(2005, 11, 01);
			declaration.JE_HouseBill = "31528";
			declaration.JE_MasterBill = "MasterBill";
			declaration.JE_RL_NKOrigin = "GBLON";
			declaration.JE_RL_NKFinalDestination = "AUSYD";
			declaration.JE_ApplicationCode = Core.Constants.AUCustoms.ImportMessagingMode.ForceCMRMessages;
			declaration.MessageInitiator = new SendsMessagesToCustomsShutterUpperer();

